@use 'tokens' as *;

/* 20261007_정회원안내: 정회원 혜택 안내 (/about/member) */
// 구조: .main-body > .about-member > 안내 패널 + 분류 탭(ds-tabs--pill) + 혜택 카드 목록

.about-member {
  display: flex;
  flex-direction: column;
  gap: 60px;
  padding-block: 60px 120px;
  color: $neutral-800;
  word-break: keep-all;

  :where(h2, h3, p, ul) {
    margin: 0;
  }
  :where(ul) {
    padding: 0;
    list-style: none;
  }
}
main:has(.about-member) > .page-banner {
  margin-top: 0;
}

// 상단 안내 패널
.about-member__intro {
  display: flex;
  align-items: center;
  gap: 60px;
  padding: 60px;
  border-radius: 24px;
  background: $primary-subtle;
}
.about-member__intro-text {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
  min-width: 0;
  color: $text-auth-secondary;
  font-size: 18px;
  line-height: 1.6;

  h2 {
    color: $neutral-900;
    font-size: 44px;
    font-weight: $font-weight-design-bold;
    line-height: 1.4;
    letter-spacing: -0.44px;
  }
}
.about-member__eyebrow {
  color: $primary-600;
  font-size: $font-size-md;
  font-weight: $font-weight-design-bold;
  line-height: 1.5;
}
.about-member__target {
  padding: 8px 16px;
  border-radius: $radius-pill;
  background: $white;
  font-size: $font-size-md;
  line-height: 1.5;
}
.about-member__visual {
  flex: none;
  width: 200px;
  height: auto;
}

// 혜택 목록
.about-member__benefits {
  display: flex;
  flex-direction: column;
  gap: 60px;
}
.about-member__cards {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}
.about-member__card {
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 32px;
  border: 1px solid $neutral-200;
  border-radius: 24px;
  background: $white;

  &[hidden] {
    display: none;
  }
}
.about-member__head {
  display: flex;
  align-items: center;
  gap: 16px;
}
.about-member__icon {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border-radius: 16px;
  background: $primary-subtle;

  img {
    width: 40px;
    height: 40px;
  }
}
.about-member__committee {
  flex: 1 1 0;
  min-width: 0;
  color: $primary-600;
  font-size: $font-size-md;
  font-weight: $font-weight-design-bold;
  line-height: 1.5;
}
.about-member__title {
  color: $neutral-900;
  font-size: 20px;
  font-weight: $font-weight-design-bold;
  line-height: 1.5;
}
.about-member__text,
.about-member__list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  color: $text-auth-secondary;
  font-size: $font-size-md;
  line-height: 1.5;
}
.about-member__list li {
  position: relative;
  padding-left: 14px;

  &::before {
    position: absolute;
    top: 0;
    left: 0;
    content: '•';
  }
}

/* ---------- 모바일 ---------- */
@media (max-width: $breakpoint-mobile) {
  .about-member {
    gap: 24px;
    padding-block: 40px;
  }
  .about-member__intro {
    padding: 20px;
    border-radius: 20px;
  }
  .about-member__intro-text {
    gap: 12px;
    font-size: $font-size-md;
    line-height: 1.5;

    h2 {
      font-size: 24px;
      line-height: 1.35;
      letter-spacing: -0.6px;
    }
  }
  .about-member__target {
    padding: 6px 12px;
  }
  .about-member__visual {
    display: none;
  }
  .about-member__benefits {
    gap: 24px;
  }
  .about-member__cards {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
  }
  .about-member__card {
    gap: 12px;
    padding: 20px;
    border-radius: 20px;
  }
  .about-member__head {
    gap: 12px;
  }
  .about-member__icon {
    width: 48px;
    height: 48px;
    border-radius: 12px;

    img {
      width: 32px;
      height: 32px;
    }
  }
  .about-member__title {
    font-size: $font-size-md;
  }
}
