@use 'sass:list';
@use 'sass:map';
@use 'tokens' as *;

/* 20261012_실시간 스트리밍: 현장보수교육 실시간 스트리밍(수강자·운영자) */

// 스트리밍 전용 값(Figma neutral/gray-700·600, 레이아웃 치수)
$streaming-line: #39414b;
$streaming-divider: $text-auth-secondary;
$streaming-black: #000;
$streaming-notice-tint: rgb(113 58 204 / 16%);
$streaming-side-width: 440px;
$streaming-side-width-tablet: 320px;
$streaming-chat-min-height: 400px;
$streaming-chat-height-mobile: 500px;
$streaming-chat-panel-width: 320px;
$streaming-time-width: 80px;
$streaming-play-size: 96px;
$streaming-play-size-mobile: 56px;
$streaming-dialog-width: 520px;
$streaming-dialog-width-mobile: 328px;
$streaming-notice-input-min-height: 152px;
$streaming-dim-opacity: 0.45;
$streaming-breakpoint-tablet: 1279px;
// 가로 모드 휴대폰(예: 844×390)
$streaming-landscape: '(max-width: 932px) and (max-height: 500px) and (orientation: landscape)';

// 문서 미리보기 크기: PC · 태블릿 · 모바일
$streaming-preview: (
  pc: (
    208px,
    126px,
    168px,
  ),
  tablet: (
    148px,
    90px,
    120px,
  ),
  mobile: (
    240px,
    160px,
    212px,
  ),
);

@mixin preview-size($key) {
  $size: map.get($streaming-preview, $key);

  height: list.nth($size, 1);

  img {
    width: list.nth($size, 2);
    height: list.nth($size, 3);
  }
}

// 페이지 배경
.edu-streaming-site {
  color: $white;
  background: $neutral-900;
}

.edu-streaming {
  min-height: 100dvh;
  overflow-x: clip;
  color: $white;
  background: $neutral-900;

  h1,
  h2,
  h3,
  p {
    margin: 0;
  }
}

/* 상단: 강연 제목 · 강의실 나가기 */
.edu-streaming__header {
  display: flex;
  align-items: center;
  gap: $space-5;
  padding: $space-9 40px;
  border-bottom: 1px solid $streaming-line;
  background: $neutral-800;
}

.edu-streaming__heading {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  line-height: $line-height-body;

  h1 {
    font-size: $font-size-xl;
    font-weight: $font-weight-design-bold;
    line-height: $line-height-body;
  }
}

.edu-streaming__eyebrow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: $space-5;
  color: $neutral-400;
  font-size: $font-size-base;

  // 운영자: 구분선 + 총 접속시간
  p + p {
    display: flex;
    align-items: center;
    gap: $space-5;

    &::before {
      width: 1px;
      height: 12px;
      background: $streaming-divider;
      content: '';
    }
  }
}

.edu-streaming__tools {
  display: flex;
  align-items: center;
  gap: $space-5;
}

.edu-streaming__tools-label {
  display: none;
  flex: 1 1 0;
  font-size: $font-size-base;
  font-weight: $font-weight-design-bold;
  line-height: $line-height-body;
}

.edu-streaming__attendee-button em {
  color: $primary-600;
  font-style: normal;
}

/* 본문: 영상 · 참여 패널 */
.edu-streaming__layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) $streaming-side-width;
  gap: $space-11;
  align-items: stretch;
  padding: $space-11;
}

.edu-streaming__stage {
  display: flex;
  flex-direction: column;
  gap: $space-7;
  min-width: 0;
}

.edu-streaming__video {
  overflow: hidden;
  border: 1px solid $streaming-line;
  border-radius: $input-radius;
  background: $streaming-black;
}

.edu-streaming__screen {
  display: flex;
  align-items: center;
  justify-content: center;
  background: $streaming-black;
}

// 외부 플레이어 컨테이너: 16:9 유지
.edu-streaming__player {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: $streaming-black;

  > :is(iframe, video) {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    border: 0;
  }
}

.edu-streaming__play {
  display: grid;
  width: $streaming-play-size;
  height: $streaming-play-size;
  border-radius: $radius-pill;
  color: $neutral-900;
  background: $white;
  font-size: 36px;
  font-weight: $font-weight-design-bold;
  line-height: 1.25;
  place-items: center;
}

.edu-streaming__controls {
  display: flex;
  align-items: center;
  gap: $space-5;
  padding: $space-7;
  background: $neutral-800;
}

.edu-streaming__live {
  flex: 1 1 0;
  font-size: $font-size-base;
  font-weight: $font-weight-design-bold;
  line-height: $line-height-body;
  white-space: nowrap;

  span {
    margin-right: $space-1;
  }
}

.edu-streaming__control-actions {
  display: flex;
  align-items: center;
  gap: $space-5;
}

.edu-streaming__text-button {
  padding: 0;
  border: 0;
  color: $white;
  background: none;
  font-size: $font-size-base;
  font-weight: $font-weight-design-bold;
  line-height: $line-height-body;
  cursor: pointer;
}

// 전체화면에서만 보이는 버튼
.edu-streaming__fullscreen-only,
.edu-streaming__chat-close {
  display: none;
}

/* 강연초록 다운로드 */
.edu-streaming__abstract {
  display: flex;
  align-items: center;
  gap: $space-7;
  padding: $space-11;
  border: 1px solid $streaming-line;
  border-radius: $input-radius;
  background: $neutral-800;
}

.edu-streaming__abstract-info {
  display: flex;
  flex: 1 1 0;
  align-items: center;
  gap: $space-5;
  min-width: 0;
  line-height: $line-height-body;

  h2 {
    font-size: 18px;
    font-weight: $font-weight-design-bold;
    line-height: $line-height-body;
  }

  p {
    margin-top: $space-1;
    color: $neutral-400;
    font-size: $font-size-base;
  }
}

// download(R/300/20)
.edu-streaming .material-symbols-rounded {
  font-size: 20px;
  font-variation-settings:
    'FILL' 0,
    'wght' 300,
    'GRAD' 0,
    'opsz' 20;
}

.edu-streaming__abstract-icon {
  flex: none;
  width: 20px;
}

/* 우측: 첨부자료 · 채팅 */
.edu-streaming__side {
  display: flex;
  flex-direction: column;
  gap: $space-7;
  min-width: 0;
}

// 탭은 모바일에서만 사용
.edu-streaming__tabs {
  display: none;
}

.edu-streaming__attachment {
  display: flex;
  flex-direction: column;
  gap: $space-5;
  padding: $space-11;
  border: 1px solid $streaming-line;
  border-radius: $input-radius;
  background: $neutral-800;
}

.edu-streaming__attachment-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: $space-3;
  line-height: $line-height-body;

  h2 {
    font-size: 18px;
    font-weight: $font-weight-design-bold;
  }

  span {
    color: $neutral-400;
    font-size: $font-size-base;
  }
}

.edu-streaming__preview {
  @include preview-size(pc);

  display: flex;
  align-items: center;
  justify-content: center;
  padding: $space-7;
  overflow: hidden;

  img {
    display: block;
    background: $white;
  }
}

.edu-streaming__pager {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: $space-5;
  font-size: $font-size-base;
  line-height: $line-height-body;
}

// arrow_back_ios_new · arrow_forward_ios(R/400/16)
.edu-streaming__pager-button {
  display: grid;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 0;
  color: $white;
  background: none;
  cursor: pointer;
  place-items: center;

  &[aria-disabled='true'] {
    cursor: default;
  }

  .edu-streaming & .material-symbols-rounded {
    font-size: 16px;
    font-variation-settings:
      'FILL' 0,
      'wght' 400,
      'GRAD' 0,
      'opsz' 16;
  }
}

.edu-streaming__file {
  display: flex;
  align-items: center;
  gap: $space-3;

  p {
    flex: 1 1 0;
    min-width: 0;
    overflow-wrap: anywhere;
    color: $neutral-400;
    font-size: $font-size-base;
    line-height: $line-height-body;
  }
}

/* 실시간 채팅 */
.edu-streaming__chat {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  min-height: $streaming-chat-min-height;
  overflow: hidden;
  border: 1px solid $streaming-line;
  border-radius: $input-radius;
  background: $neutral-800;
}

.edu-streaming__chat-head {
  display: flex;
  align-items: center;
  gap: $space-5;
  padding: $space-7;
  border-bottom: 1px solid $streaming-line;

  h2 {
    flex: 1 1 0;
    min-width: 0;
    font-size: 18px;
    font-weight: $font-weight-design-bold;
    line-height: $line-height-body;
  }
}

.edu-streaming__count {
  color: $neutral-400;
  font-size: $font-size-base;
  line-height: $line-height-body;
  white-space: nowrap;
}

// 고정 공지: 보라색 틴트 배경
.edu-streaming__notice {
  display: flex;
  flex: none;
  flex-direction: column;
  gap: $space-3;
  padding: $space-7;
  background: linear-gradient($streaming-notice-tint, $streaming-notice-tint), $neutral-800;
  font-size: $font-size-base;
  line-height: $line-height-body;
}

.edu-streaming__notice-head {
  display: flex;
  align-items: center;
  gap: $space-3;

  h3 {
    flex: 1 1 0;
    font-size: $font-size-base;
    font-weight: $font-weight-design-bold;
  }
}

.edu-streaming__messages {
  flex: 1 1 0;
  min-height: 0;
  padding: $space-7;
  overflow-x: clip;
  overflow-y: auto;
  scrollbar-color: $streaming-line transparent;
  scrollbar-width: thin;

  &:focus-visible {
    outline-offset: -$focus-ring-width;
  }

  ol {
    display: flex;
    flex-direction: column;
    gap: $space-9;
    margin: 0;
    padding: 0;
    list-style: none;
  }
}

// 시간 → 사람 아이콘 → 이름 → 내용
.edu-streaming__message {
  display: flex;
  align-items: flex-start;
  gap: $space-3;
  line-height: $line-height-body;

  time {
    flex: none;
    width: $streaming-time-width;
    color: $neutral-400;
    font-size: $font-size-xs;
  }

  img {
    flex: none;
  }

  div {
    display: flex;
    flex: 1 1 0;
    flex-direction: column;
    gap: $space-1;
    min-width: 0;
    font-size: $font-size-base;
    overflow-wrap: anywhere;
  }
}

// Material Symbols 아이콘(Rounded 400): 채팅 24 · 사람·고정핀 20
.edu-streaming__icon {
  flex: none;
  font-variation-settings: 'wght' 400;
  line-height: 1;
  user-select: none;

  &--20 {
    width: 20px;
    height: 20px;
    font-size: 20px;
  }

  &--24 {
    width: 24px;
    height: 24px;
    font-size: 24px;
  }
}

// 운영자 메시지: 아이콘·이름 보라색(어두운 배경에서 보이도록 primary-300)
.edu-streaming__message--operator :is(strong, .edu-streaming__icon) {
  color: $primary-300;
}

.edu-streaming__composer {
  display: flex;
  flex: none;
  align-items: center;
  gap: $space-3;
  padding: $space-7;
  border-top: 1px solid $streaming-line;
  background: $neutral-900;

  .form-field {
    flex: 1 1 0;
    min-width: 0;
  }

  input:focus {
    border-color: $primary-600;
  }
}

/* 태블릿(1024 기준) */
@media (max-width: $streaming-breakpoint-tablet) {
  .edu-streaming__layout {
    grid-template-columns: minmax(0, 1fr) $streaming-side-width-tablet;
    gap: $space-7;
    padding: $space-7;
  }

  .edu-streaming__preview {
    @include preview-size(tablet);
  }
}

// 좁은 태블릿: 강연초록을 세로 배치
@media (max-width: $breakpoint-tablet) {
  .edu-streaming__abstract {
    flex-direction: column;
    align-items: stretch;
  }

  .edu-streaming__download {
    width: 100%;
  }
}

/* 모바일 세로(360 기준) */
@media (max-width: $breakpoint-mobile) {
  .edu-streaming__header {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    padding: $space-5 $space-7;

    h1 {
      font-size: 18px;
    }
  }

  .edu-streaming__eyebrow {
    flex-direction: column;
    align-items: flex-start;
    gap: $space-1;

    p + p::before {
      display: none;
    }
  }

  // 운영자 도구: 제목 아래 별도 줄
  .edu-streaming__tools {
    grid-row: 2;
    grid-column: 1 / -1;
    margin: $space-5 (-$space-7) (-$space-5);
    padding: $space-7;
    border-top: 1px solid $streaming-line;
  }

  .edu-streaming__tools-label {
    display: block;
  }

  .edu-streaming__layout {
    display: block;
    padding: 0;
  }

  .edu-streaming__stage {
    gap: $space-5;
    padding-bottom: $space-5;
  }

  .edu-streaming__video {
    border-radius: 0;
  }

  .edu-streaming__play {
    width: $streaming-play-size-mobile;
    height: $streaming-play-size-mobile;
    font-size: $font-size-xl;
    line-height: 1.4;
  }

  .edu-streaming__controls {
    padding: $space-5;
  }

  .edu-streaming__abstract {
    flex-direction: column;
    align-items: stretch;
    padding: $space-7;
  }

  .edu-streaming__download {
    width: 100%;
  }

  .edu-streaming__side {
    gap: 0;
  }

  // 채팅 · 첨부자료 탭
  .edu-streaming .edu-streaming__tabs.ds-tabs--box {
    display: flex;
    gap: 0;
    margin: 0;
    padding: 0;
    overflow: visible;
    border-radius: 0;
    background: $neutral-800;

    > .ds-tabs__item {
      flex: 1 1 0;
      min-width: 0;
      min-height: 0;
      padding: $space-5;
      border-radius: 0;
      color: $white;
      background: $neutral-800;
      font-size: $font-size-base;
      line-height: $line-height-body;

      &[aria-selected='true'] {
        background: $primary-600;
      }
    }
  }

  .edu-streaming__panel {
    border-radius: 0;

    &:not(.is-active) {
      display: none;
    }
  }

  .edu-streaming__attachment {
    padding: $space-7;
  }

  .edu-streaming__preview {
    @include preview-size(mobile);
  }

  .edu-streaming__chat {
    flex: none;
    height: $streaming-chat-height-mobile;
    min-height: 0;
  }
}

/* 전체화면: 레터박스 영상 + 하단 컨트롤 (가로 모드 휴대폰 기본) */
.edu-streaming.is-fullscreen {
  .edu-streaming__video {
    position: fixed;
    z-index: 100;
    inset: 0;
    display: flex;
    flex-direction: column;
    border: 0;
    border-radius: 0;
  }

  .edu-streaming__screen {
    flex: 1 1 0;
    min-height: 0;
  }

  .edu-streaming__player {
    width: auto;
    max-width: 100%;
    height: 100%;
    max-height: 100%;
  }

  .edu-streaming__controls {
    padding: $space-3;
  }

  .edu-streaming__text-button {
    display: none;
  }

  .edu-streaming__fullscreen-only {
    display: inline-flex;
  }

  // 가로 채팅 열림: 영상 어둡게 + 우측 채팅 패널
  &.is-chat-open {
    .edu-streaming__video {
      right: $streaming-chat-panel-width;
    }

    .edu-streaming__controls {
      display: none;
    }

    .edu-streaming__player {
      width: 100%;
      height: auto;
      opacity: $streaming-dim-opacity;
    }

    .edu-streaming__chat {
      position: fixed;
      z-index: 101;
      top: 0;
      right: 0;
      bottom: 0;
      display: flex;
      width: $streaming-chat-panel-width;
      height: auto;
      min-height: 0;
      border-radius: $input-radius;
    }

    .edu-streaming__count {
      display: none;
    }

    .edu-streaming__chat-close {
      display: inline-flex;
    }
  }
}

// 전체화면 중 문서 스크롤 잠금
.edu-streaming-site:has(.edu-streaming.is-fullscreen) {
  overflow: hidden;
}

/* 첨부자료 확대보기: 화면 전체 */
.edu-streaming-viewer {
  width: 100%;
  max-width: none;
  height: 100dvh;
  max-height: none;
  margin: 0;
  padding: $space-11;
  border: 0;
  color: $white;
  background: $neutral-900;

  &[open] {
    display: flex;
    flex-direction: column;
    gap: $space-7;
  }

  &::backdrop {
    background: $neutral-900;
  }

  h2 {
    margin: 0;
    font-size: 18px;
    font-weight: $font-weight-design-bold;
    line-height: $line-height-body;
  }

  p {
    margin: 0;
  }
}

.edu-streaming-viewer__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: $space-5;
}

.edu-streaming-viewer__body {
  display: flex;
  flex: 1 1 0;
  align-items: center;
  justify-content: center;
  min-height: 0;
  padding: $space-7;
  overflow: auto;
  background: $neutral-800;

  img {
    display: block;
    width: auto;
    max-width: 100%;
    height: auto;
    max-height: 100%;
  }
}

.edu-streaming-viewer__pager {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: $space-5;
  color: $neutral-400;
  font-size: $font-size-base;
  line-height: $line-height-body;

  button {
    padding: 0;
    border: 0;
    color: inherit;
    background: none;
    font: inherit;

    &[aria-disabled='true'] {
      cursor: default;
    }
  }
}

/* 운영자 레이어: 공지 등록 · 현재 수강자 현황 */
.edu-streaming-dialog {
  width: min(calc(100% - #{$space-14}), $streaming-dialog-width);
  max-height: calc(100dvh - #{$space-14});
  padding: 0;
  overflow: hidden;
  border: 1px solid $streaming-line;
  border-radius: $input-radius;
  color: $white;
  background: $neutral-800;
  box-shadow: $shadow-dialog-pc;

  &::backdrop {
    background: $streaming-black;
    opacity: 0.6;
  }

  h2,
  p {
    margin: 0;
  }
}

.edu-streaming-dialog__inner {
  display: flex;
  flex-direction: column;
  gap: $space-7;
  max-height: calc(100dvh - #{$space-14});
  padding: $space-11;
  overflow-y: auto;
}

.edu-streaming-dialog__head {
  display: flex;
  align-items: center;
  gap: $space-5;

  h2 {
    flex: 1 1 0;
    font-size: $font-size-xl;
    font-weight: $font-weight-design-bold;
    line-height: $line-height-body;
  }
}

.edu-streaming-dialog__desc {
  color: $neutral-400;
  font-size: $font-size-base;
  line-height: $line-height-body;
}

// 공지 내용 입력: 공통 form-field를 어두운 배경으로 조정
.edu-streaming-dialog__field.form-field {
  gap: $space-7;

  textarea {
    min-height: $streaming-notice-input-min-height;
    padding: $space-7;
    border-color: $streaming-line;
    color: $white;
    background: $neutral-900;
    font-size: $font-size-base;
    line-height: $line-height-body;
    resize: vertical;

    &:focus {
      border-color: $primary-600;
    }
  }

  small {
    margin-top: 0;
    color: $neutral-400;
  }
}

.edu-streaming-dialog__label {
  font-size: $font-size-base;
  font-weight: $font-weight-design-bold;
  line-height: $line-height-body;
}

.edu-streaming-dialog__actions {
  display: flex;
  gap: $space-5;

  .ds-button {
    flex: 1 1 0;
    min-width: 0;
  }
}

.edu-streaming-dialog__summary {
  display: flex;
  align-items: center;
  gap: $space-5;
  margin: 0;
  padding: $space-7;
  border-radius: $input-radius;
  background: $neutral-900;
  font-weight: $font-weight-design-bold;
  line-height: $line-height-body;

  dt {
    flex: 1 1 0;
    font-size: $font-size-base;
  }

  dd {
    margin: 0;
    font-size: $font-size-xl;
  }
}

.edu-streaming-dialog__attendees {
  margin: 0;
  padding: 0;
  list-style: none;
  // 수강자가 많으면 목록 안에서 스크롤(약 5명 높이)
  max-height: 280px;
  overflow-y: auto;
  overscroll-behavior: contain;

  &:focus-visible {
    outline: 2px solid $primary-600;
    outline-offset: 2px;
  }

  li {
    display: flex;
    align-items: center;
    gap: $space-5;
    padding: $space-7;
    border-bottom: 1px solid $streaming-line;
    font-size: $font-size-base;
    line-height: $line-height-body;
  }

  strong {
    flex: 1 1 0;
    min-width: 0;
  }

  span {
    color: $neutral-400;
  }
}

.edu-streaming-dialog__close {
  width: 100%;
}

@media (max-width: $breakpoint-mobile) {
  .edu-streaming-viewer {
    padding: $space-7;
  }

  .edu-streaming-dialog {
    width: min(calc(100% - #{$space-14}), $streaming-dialog-width-mobile);
  }

  .edu-streaming-dialog__inner {
    padding: $space-7;
  }
}

/* 가로 모드 휴대폰: 전체화면을 종료하면 태블릿형 2단 배치 */
@media #{$streaming-landscape} {
  .edu-streaming__header {
    padding: $space-5 $space-7;
  }

  .edu-streaming-viewer {
    padding: $space-7;
  }

  .edu-streaming__play {
    width: $streaming-play-size-mobile;
    height: $streaming-play-size-mobile;
    font-size: $font-size-xl;
    line-height: 1.4;
  }
}
