@use 'tokens' as *;

/* 인트로: 통합 서비스 진입 화면 (/intro) */
// 구조: .intro > 배경(.intro__visual) + 헤더 + main(.intro__body) + 푸터

// Figma 전용 값
$intro-card-border: #ad99ff; // primary/primary-300
$intro-surface-mobile: #f8f5ff;
$intro-content-width: 1440px;
$intro-card-height: 274px;
$intro-cta-width: 540px;
$intro-tablet-grid-width: 720px;

.intro {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
  padding: 0 $space-9 60px;
  overflow: hidden;
  color: $neutral-800;
  word-break: keep-all;
  background: $white image-set(url('/assets/intro/intro-bg.jpg') 1x, url('/assets/intro/intro-bg-2x.jpg') 2x) center
    top / cover no-repeat;

  :where(h1, h2, p, ul) {
    margin: 0;
  }
  :where(ul) {
    padding: 0;
    list-style: none;
  }
}

// 배경 광원: 1920 기준 좌표를 화면 가운데에 고정
.intro__visual {
  position: absolute;
  top: 0;
  left: 50%;
  width: 1920px;
  height: 1080px;
  pointer-events: none;
  transform: translateX(-50%);
}
.intro__glow {
  position: absolute;
  width: 920px;
  height: 920px;
  background: url('/assets/intro/glow-purple.svg') center / 100% 100% no-repeat;

  &--purple-1 {
    top: -354px;
    left: 1220px;
  }
  &--purple-2 {
    top: 123px;
    left: -235px;
  }
  &--purple-3 {
    top: 123px;
    left: 393px;
  }
  &--purple-4 {
    top: 702px;
    left: 675px;
  }
  &--blue-1,
  &--blue-2 {
    width: 800px;
    height: 800px;
    background-image: url('/assets/intro/glow-blue.svg');
  }
  &--blue-1 {
    top: 617px;
    left: -62px;
  }
  &--blue-2 {
    top: 177px;
    left: 923px;
  }
}

// 헤더: 로고 + 로그인·회원가입
.intro__header {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: $space-9;
  width: min(100%, $intro-content-width);
  padding-block: 40px $space-9;
}
.intro__logo {
  display: block;
  width: 220px;
  height: auto;
}
.intro__member-nav {
  display: flex;
  gap: $space-1;
}
.intro__member-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: $space-2 $space-7;
  border-radius: $radius-pill;
  color: $white;
  font-size: $font-size-base;
  font-weight: $font-weight-design-bold;
  line-height: 1.6;
  white-space: nowrap;
  background: $primary-600;
  transition: background-color $motion-fast ease;

  &:hover {
    background: $primary-hover;
  }
}

// 본문
.intro > main {
  position: relative;
  width: 100%;
}
.intro__body {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 52px;
  width: min(100%, $intro-content-width);
  margin: $space-section auto 0;
}
.intro__heading {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: $space-7;
  text-align: center;
}
.intro__eyebrow {
  color: $primary-600;
  font-size: $font-size-base;
  font-weight: $font-weight-design-bold;
  line-height: 1.5;
}
.intro__title {
  font-size: 44px;
  font-weight: $font-weight-design-bold;
  line-height: 1.4;
  letter-spacing: -0.44px;
}
.intro__lead {
  color: $text-auth-secondary;
  font-size: 18px;
  line-height: 1.6;
}

// 서비스 카드 목록: PC 4열, 태블릿 2열, 모바일 1열
.intro__services {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 40px;
  width: 100%;
}
.intro-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: $space-8;
  height: 100%;
  min-height: $intro-card-height;
  padding: $space-12;
  overflow: hidden;
  border: 1px solid $intro-card-border;
  border-radius: 24px;
  background: $white;
  transition:
    background-color $motion-fast ease,
    border-color $motion-fast ease,
    box-shadow $motion-fast ease,
    transform $motion-fast ease;

  > :not(.intro-card__watermark) {
    position: relative;
  }
}
.intro-card__number {
  color: $primary-600;
  font-size: $font-size-base;
  font-weight: $font-weight-design-bold;
  line-height: 22px;
  letter-spacing: 0.84px;
}
.intro-card__title {
  font-size: 28px;
  font-weight: $font-weight-design-bold;
  line-height: 1.4;
  letter-spacing: -0.14px;
}
.intro-card__desc {
  color: $text-auth-secondary;
  font-size: $font-size-md;
  line-height: 1.5;
}
.intro-card__more {
  display: inline-flex;
  align-items: center;
  gap: $space-1;
  color: $primary-600;
  font-size: $font-size-md;
  font-weight: $font-weight-design-bold;
  line-height: 1.5;

  // arrow_outward(R/400/20) 16px
  .material-symbols-rounded {
    font-size: 16px;
    font-variation-settings:
      'FILL' 0,
      'wght' 400,
      'GRAD' 0,
      'opsz' 20;
  }
}

// 강조 카드 워터마크(협회 심볼): 196×192.5 그룹을 우측 하단에 배치
.intro-card__watermark {
  position: absolute;
  right: -15px;
  bottom: -45.5px;
  width: 196px;
  height: 192.5px;
  opacity: 0;
  pointer-events: none;
  transition: opacity $motion-fast ease;

  img {
    position: absolute;
    display: block;
    max-width: none;
    height: auto;
    opacity: 0.2;

    &:nth-child(1) {
      top: 0;
      left: 0;
      width: 63.82%;
    }
    &:nth-child(2) {
      top: 0.1%;
      left: 0;
      width: 35.2%;
    }
    &:nth-child(3) {
      top: 0;
      left: 36.16%;
      width: 63.84%;
    }
    &:nth-child(4) {
      top: 0.1%;
      left: 36.16%;
      width: 35.22%;
    }
    &:nth-child(5) {
      top: 56.85%;
      left: 47.02%;
      width: 13.08%;
      mix-blend-mode: multiply;
    }
    &:nth-child(6) {
      top: 25.27%;
      left: 14.55%;
      width: 45.34%;
    }
    &:nth-child(7) {
      top: 15.6%;
      left: 50%;
      width: 11.04%;
      mix-blend-mode: multiply;
    }
    &:nth-child(8) {
      top: 18.68%;
      left: 50.71%;
      width: 45.35%;
    }
  }
}

// hover·focus 상태: 보라 배경 카드
.intro-card:hover,
.intro-card:focus-visible {
  border-color: $primary-hover;
  box-shadow: $shadow-md;
  color: $white;
  background: $primary-600;

  .intro-card__watermark {
    opacity: 1;
  }
  .intro-card__number {
    color: $intro-card-border;
  }
  .intro-card__desc {
    color: $primary-subtle;
  }
  .intro-card__more {
    color: $white;
  }
}
.intro-card:hover,
.intro-card:focus-visible {
  transform: translateY(-$space-1);
}
.intro-card:focus-visible {
  outline-offset: 3px;
}

// 선가입 회원등록 안내
.intro__pre-member {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: $space-5;
  width: min(100%, $intro-cta-width);
  min-height: 56px;
  padding: $space-3 $space-11;
  border: 1px solid $neutral-300;
  border-radius: $radius-pill;
  font-size: $font-size-md;
  line-height: 1.5;
  background: $white;
  transition: border-color $motion-fast ease;

  &:hover {
    border-color: $primary-600;
  }
  &:hover .intro__pre-member-link {
    text-decoration: underline;
    text-underline-offset: 3px;
  }
}
.intro__pre-member-link {
  display: inline-flex;
  align-items: center;
  gap: $space-1;
  color: $primary-600;
  font-weight: $font-weight-design-bold;

  // arrow_forward_ios(R/400/16)
  .material-symbols-rounded {
    font-size: 16px;
    font-variation-settings:
      'FILL' 0,
      'wght' 400,
      'GRAD' 0,
      'opsz' 20;
  }
}

// 저작권
.intro__footer {
  position: relative;
  margin-top: 52px;
}
.intro__copyright {
  color: $neutral-500;
  font-size: $font-size-xs;
  line-height: 1.5;
  text-align: center;
}

@media (prefers-reduced-motion: reduce) {
  .intro-card,
  .intro-card__watermark {
    transition: none;
  }
  .intro-card:hover,
  .intro-card:focus-visible {
    transform: none;
  }
}

// 태블릿: 카드 2×2
@media (max-width: $breakpoint-card-grid-three) {
  .intro__services {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: $space-11;
    width: min(100%, $intro-tablet-grid-width);
  }
}

// 모바일: Figma Intro_MO_360
@media (max-width: $breakpoint-mobile) {
  .intro {
    padding: 0 $space-7 40px;
    background: $intro-surface-mobile
      image-set(url('/assets/intro/intro-bg.jpg') 1x, url('/assets/intro/intro-bg-2x.jpg') 2x) 80% top / auto 100%
      no-repeat;
    background-blend-mode: multiply;
  }
  .intro__visual {
    display: none;
  }
  .intro__header {
    align-items: center;
    padding-block: $space-7;
  }
  .intro__logo {
    width: 160px;
  }
  .intro__member-nav {
    gap: 3px;
  }
  .intro__member-link {
    min-height: 30px;
    padding: 0 $space-5;
    font-size: $font-size-xs;
    line-height: 1.5;
  }
  .intro__body {
    gap: 40px;
    margin-top: 28px;
  }
  .intro__heading {
    gap: $space-5;
  }
  .intro__title {
    font-size: 28px;
    line-height: 1.3;
    letter-spacing: -0.28px;
  }
  .intro__lead {
    font-size: $font-size-md;
    line-height: 1.5;
  }
  .intro__services {
    grid-template-columns: minmax(0, 1fr);
    gap: $space-5;
    width: 100%;
  }
  .intro-card {
    gap: $space-3;
    min-height: 0;
    padding: $space-9;
    border-radius: $radius-md;
  }
  .intro-card__title {
    font-size: 24px;
    letter-spacing: -0.12px;
  }
  .intro-card__watermark {
    right: -8px;
    bottom: -29.7px;
    width: 142px;
    height: 139.5px;
  }
  .intro__pre-member {
    gap: $space-3;
    width: 100%;
    padding: $space-7;
    font-size: $font-size-base;
  }
  .intro__footer {
    margin-top: 40px;
  }
  .intro__copyright span {
    display: block;
  }
}
