@use '../foundation/tokens' as ds;
@use '../../../tokens' as t;

$main-width: 1440px;
$main-ink: ds.$color-neutral-900;
$main-copy: ds.$color-neutral-800;
$main-muted: ds.$color-neutral-700;
$main-purple: ds.$color-main-purple;
$main-card-radius: ds.$radius-lg;

body.main-page .layout-container:not(.site-footer__inner) {
  width: min($main-width, calc(100% - 40px));
}

.main-b {
  color: $main-ink;
}

// 메인 배너: Figma 최종 확정안 B안 4장 슬라이드 (높이 700, 문구 top 197, 인디케이터 top 443)
.main-b-hero {
  position: relative;
  height: 700px;
  overflow: hidden;
  background: ds.$color-background-01;

  &__slider,
  .swiper-wrapper,
  &__slide {
    height: 100%;
  }

  &__slide {
    position: relative;
    overflow: hidden;
  }

  &__image {
    position: absolute;
    inset: 0;
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
  }

  &__inner {
    position: relative;
    height: 100%;
  }

  &__copy {
    position: absolute;
    top: 197px;
    left: 0;
    max-width: 760px;
  }

  &__title {
    margin: 0;
    font-size: 60px;
    font-weight: 700;
    line-height: 1.25;
    letter-spacing: -0.6px;

    span {
      display: block;
    }
  }

  &__description {
    margin: 8px 0 0;
    font-size: 18px;
    line-height: 1.6;
  }

  // PC·모바일 줄바꿈 위치가 달라 화면별 br만 표시
  &__break--mo {
    display: none;
  }

  // 현재 슬라이드의 문구만 아래에서 위로 나타남
  .swiper-slide-active &__title span,
  .swiper-slide-active &__description {
    animation: main-b-copy-in 1200ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }

  .swiper-slide-active &__title span + span {
    animation-delay: 240ms;
  }

  .swiper-slide-active &__description {
    animation-delay: 520ms;
  }

  // 인디케이터: 8px 점 4개(간격 6), 현재 슬라이드 진한 회색
  &__controls {
    position: absolute;
    z-index: 2;
    top: 443px;
    left: 50%;
    transform: translateX(-50%);
    pointer-events: none;
  }

  &__pagination {
    display: flex;
    gap: 6px;
    pointer-events: auto;

    .swiper-pagination-bullet {
      width: 8px;
      height: 8px;
      margin: 0;
      border-radius: 50%;
      background: rgb(35 42 49 / 25%);
      opacity: 1;
    }

    .swiper-pagination-bullet-active {
      background: $main-ink;
    }

    // Swiper 기본 가로 간격(margin 0 4px)보다 우선해 Figma 롤링(50×8, 간격 6)과 맞춤
    &.swiper-pagination-horizontal .swiper-pagination-bullet {
      margin: 0;
    }
  }
}

.main-b-services {
  padding: 80px 0;

  &__inner {
    display: grid;
    grid-template-columns: 880px 520px;
    gap: 40px;
    height: 516px;
  }
}

.main-b-quick {
  display: flex;
  flex-direction: column;
  gap: 24px;

  &__grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    grid-template-rows: repeat(3, 156px);
    gap: 24px 16px;
  }

  &__card {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: 20px 24px;
    border-radius: $main-card-radius;
    background: ds.$color-background-card-purple;
    transition:
      transform 180ms ease,
      box-shadow 180ms ease;

    &:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 24px rgb(113 58 204 / 14%);
    }

    strong {
      font-size: 20px;
      line-height: 1.5;
      color: $main-copy;

      span {
        display: block;
      }
    }

    // 새 창 열림 표시(덴톡·전체 메뉴와 같은 arrow_outward)
    strong .main-b-quick__external {
      display: inline-block;
      margin-left: 2px;
      font-size: 0.9em;
      font-weight: 400;
      vertical-align: -0.12em;
    }

    img {
      align-self: flex-end;
      width: 48px;
      height: 48px;
      object-fit: contain;
    }
  }
}

.main-b-promo {
  width: 520px;
  height: 516px;
  border-radius: $main-card-radius;

  &__slide {
    position: relative;
    overflow: hidden;
    border-radius: $main-card-radius;
    background: ds.$color-primary-50;

    > picture,
    > picture img {
      display: block;
      width: 100%;
      height: 100%;
    }

    > picture img {
      object-fit: cover;
    }

    &--education {
      padding: 144px 40px 72px;
      background: ds.$color-background-card-purple;

      > img {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
        opacity: 0.34;
      }
    }
  }

  &__copy {
    position: relative;
    z-index: 1;

    h2 {
      margin: 0 0 20px;
      font-size: 34px;
      line-height: 1.4;
      letter-spacing: -0.34px;
    }

    p {
      margin: 0;
      font-size: 16px;
      line-height: 1.55;
    }
  }

  // 배너 인디케이터(Figma 수정안은 숨김이지만 슬라이드 확인을 위해 표시)
  &__pagination.swiper-pagination-horizontal {
    position: absolute;
    z-index: 2;
    bottom: 28px;
    left: 36px;
    width: auto;

    .swiper-pagination-bullet {
      width: 8px;
      height: 8px;
      margin: 0 4px 0 0;
      background: ds.$color-neutral-200;
      opacity: 1;
    }

    .swiper-pagination-bullet-active {
      background: $main-ink;
    }
  }
}

.main-section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 62px;

  h2 {
    margin: 0;
    font-size: 44px;
    line-height: 1.4;
    letter-spacing: -0.44px;
  }

  &__more {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    color: ds.$color-neutral-500;
    font-size: 16px;
    font-weight: 700;
    line-height: 1.5;

    .material-icon {
      width: 16px;
      height: 16px;
      font-size: 16px;
    }
  }
}

.main-b-news {
  padding: 80px 0;
  background: ds.$color-background-main-purple;

  &__inner {
    display: flex;
    flex-direction: column;
    gap: 32px;
  }

  &__tabs-scroll {
    overflow: hidden;
  }

  &__tabs {
    min-width: max-content;
    overflow: visible;
  }

  &__list {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    grid-template-rows: repeat(2, 216px);
    gap: 16px 24px;
  }

  &__item {
    position: relative;
    height: 216px;
    padding: 24px;
    overflow: hidden;
    border: 1px solid ds.$color-neutral-200;
    border-radius: $main-card-radius;
    background: ds.$color-white;
    transition: border-color 0.2s ease;

    &:focus-within {
      border-color: $main-purple;
    }

    // 카드 전체를 링크 영역으로: 포커스 링은 카드 테두리에 표시
    > a {
      display: block;
      color: inherit;

      &::after {
        position: absolute;
        inset: 0;
        border-radius: inherit;
        content: '';
      }

      &:focus-visible {
        outline: none;
      }
    }

    &:has(> a:focus-visible) {
      outline: t.$focus-ring-width solid t.$focus-ring-color;
      outline-offset: t.$focus-ring-offset;
    }

    @media (hover: hover) {
      &:hover {
        border-color: $main-purple;
      }
    }

    time {
      display: block;
      margin-top: 12px;
      color: ds.$color-neutral-400;
      font-size: 16px;
      line-height: 1.5;
    }
  }

  &__category {
    min-height: 30px;
    margin-bottom: 12px;
    padding: 6px 10px;
    color: ds.$color-badge-purple-text;
    line-height: 18px;
    background: ds.$color-badge-purple-bg;
  }

  &__title {
    margin: 0 0 8px;
    overflow: hidden;
    font-size: 20px;
    line-height: 1.5;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  &__description {
    display: -webkit-box;
    margin: 0;
    overflow: hidden;
    color: ds.$color-neutral-600;
    font-size: 16px;
    line-height: 1.5;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }
}

.main-b-youtube {
  padding: 80px 0 120px;

  &__inner {
    display: flex;
    flex-direction: column;
    gap: 32px;
  }

  &__list {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 24px;
  }

  &__card {
    display: flex;
    min-width: 0;
    height: 394.648px;
    flex-direction: column;

    &:focus-visible {
      .main-b-youtube__copy strong,
      .main-b-youtube__copy > span {
        color: $main-purple;
      }
    }

    @media (hover: hover) {
      &:hover {
        .main-b-youtube__copy strong,
        .main-b-youtube__copy > span {
          color: $main-purple;
        }
      }
    }
  }

  &__thumbnail {
    display: block;
    width: 100%;
    height: 284.648px;
    border-radius: $main-card-radius;
    object-fit: cover;
  }

  &__copy {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 24px 8px 0;

    // 제목은 한 줄 말줄임, 새 창 아이콘은 제목 길이와 관계없이 항상 표시
    strong {
      display: flex;
      align-items: center;
      gap: 4px;
      min-width: 0;
      color: $main-ink;
      font-size: 20px;
      line-height: 1.5;
      transition: color 0.2s ease;
    }

    > span {
      display: -webkit-box;
      overflow: hidden;
      color: $main-muted;
      font-size: 16px;
      line-height: 1.5;
      transition: color 0.2s ease;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: 2;
    }
  }
}

// 대표 사이트 메인에서만 피그마의 반투명 오버레이 헤더를 적용한다.
body.main-page {
  .site-header {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 101.687px;
    color: $main-ink;
    background: rgb(255 255 255 / 50%);
    backdrop-filter: blur(2px);
  }

  .site-header__inner {
    align-items: flex-end;
    height: 101.687px;
    padding: 40px 0 20px;
  }

  .site-logo--header,
  .site-logo--header .site-logo__image {
    width: 220px;
    height: 41.687px;
  }

  .site-header__navigation,
  .primary-nav {
    display: flex;
    align-items: center;
  }

  .utility-nav,
  .primary-nav__search,
  .primary-nav__education-cart {
    display: none;
  }

  .primary-nav {
    gap: 24px;
  }

  .primary-nav__links {
    gap: 32px;
  }

  .primary-nav__item {
    height: 42px;
    margin: 0;
    padding: 0;
  }

  .primary-nav__link {
    height: 42px;
    color: $main-ink;
    font-size: 20px;
    line-height: 1.5;
  }

  .primary-nav__main-login {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 58px;
    min-height: 34px;
    padding: 6px 16px;
    border-radius: ds.$radius-pill;
    color: ds.$color-white;
    font-size: 14px;
    font-weight: 700;
    background: $main-purple;
  }

  .primary-nav__icon-button {
    color: $main-ink;
  }
}

// 공통 헤더(흰 배경)보다 우선해 메인 배너 위 반투명 헤더를 유지한다.
body.main-page:not(.regional-site):not(.english-site) .site .site-header {
  background: rgb(255 255 255 / 50%);
  backdrop-filter: blur(2px);
}

// 공통 헤더의 사이트 분기 선택자보다 우선하여 메인 시안의 정확한 내부 여백을 유지한다.
body.main-page .site .site-header {
  height: 101.687px;
}

body.main-page .site .site-header__inner {
  height: 101.687px;
  padding: 40px 0 20px;
}

@keyframes main-b-copy-in {
  from {
    opacity: 0;
    transform: translateY(24px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .main-b-hero .swiper-slide .main-b-hero__title span,
  .main-b-hero .swiper-slide .main-b-hero__description {
    opacity: 1;
    transform: none;
    animation: none;
  }
}

// 1440px 콘텐츠가 들어가지 않는 화면: 퀵메뉴는 남은 폭, 배너는 비율 유지로 축소
@media (max-width: 1480px) and (min-width: 1101px) {
  .main-b-services__inner {
    grid-template-columns: minmax(0, 1fr) minmax(0, 520px);
    height: auto;
  }

  .main-b-quick__grid {
    grid-template-rows: repeat(3, minmax(156px, auto));
  }

  .main-b-quick .main-b-quick__card {
    padding-inline: 16px;
    word-break: keep-all;
  }

  .main-b-quick .main-b-quick__card--fluid strong span {
    display: inline;
  }

  .main-b-promo {
    width: 100%;
    height: auto;
    aspect-ratio: 520 / 516;
  }
}

@media (max-width: 1100px) and (min-width: #{t.$breakpoint-mobile + 1}) {
  .main-b-services__inner {
    grid-template-columns: 1fr;
    height: auto;
  }

  .main-b-promo {
    width: min(100%, 520px);
    height: auto;
    aspect-ratio: 520 / 516;
  }

  .main-b-hero__copy {
    left: 40px;
  }
}

@media (max-width: 700px) {
  body.main-page .layout-container:not(.site-footer__inner) {
    width: 100%;
  }

  body.main-page {
    .site-header,
    .site-header__inner {
      height: 62.667px;
    }

    .site-header {
      background: rgb(255 255 255 / 50%);
      backdrop-filter: none;
    }

    .site-header__inner {
      align-items: center;
      width: 100%;
      padding: 16px;
    }

    .site-logo--header,
    .site-logo--header .site-logo__image {
      width: 160px;
      height: 30.667px;
    }

    .primary-nav__main-login {
      display: none;
    }

    .primary-nav__icon-button {
      width: 28px;
      height: 28px;

      .material-icon {
        width: 28px !important;
        height: 28px !important;
        font-size: 28px !important;
      }
    }
  }

  body.main-page .site .site-header,
  body.main-page .site .site-header__inner {
    height: 62.667px;
  }

  body.main-page .site .site-header__inner {
    padding: 16px;
  }
}

// 모바일(767px 이하): Figma 수정안 대표 메인_MO (360px 기준)
@media (max-width: t.$breakpoint-mobile) {
  body.main-page .main-b-hero__inner,
  body.main-page .main-b-services__inner,
  body.main-page .main-b-news__inner,
  body.main-page .main-b-youtube__inner {
    width: 100%;
  }

  // 메인 배너: 높이 512, 문구 위·인물 이미지 아래(높이 256)
  .main-b-hero {
    height: 512px;
    background: ds.$color-white;

    &__image {
      top: auto;
      bottom: 0;
      height: 256px;
      object-position: 69.9% center;
    }

    // 문구 영역 배경과 이미지 상단을 자연스럽게 잇는 그라데이션
    &__slide::after {
      position: absolute;
      inset: 0 0 auto;
      height: 297px;
      background: linear-gradient(to bottom, rgb(237 233 226 / 0%) 0%, #eeeae5 87.5%, rgb(239 235 230 / 0%) 100%);
      content: '';
    }

    &__inner {
      z-index: 1;
    }

    &__copy {
      top: 31px;
      right: 16px;
      left: 20px;
      max-width: none;
    }

    &__title {
      color: $main-copy;
      font-size: 36px;
      letter-spacing: -0.54px;
      word-break: keep-all;
    }

    &__description {
      margin-top: 16px;
      color: $main-copy;
      font-size: 16px;
      line-height: 1.5;
      word-break: keep-all;
    }

    &__break--pc {
      display: none;
    }

    &__break--mo {
      display: inline;
    }

    // 인디케이터: 현재 슬라이드 문구 아래 16px (main.js에서 위치 계산)
    &__controls {
      top: var(--main-b-hero-dots-top, 246px);
      left: 20px;
      width: auto;
      transform: none;
    }

    &__pagination {
      .swiper-pagination-bullet {
        background: ds.$color-white;
      }

      .swiper-pagination-bullet-active {
        background: $main-ink;
      }
    }
  }

  // 주요 서비스: 퀵메뉴 2열씩 가로 스크롤 + 법률·노무 배너
  .main-b-services {
    padding: 40px 0;

    &__inner {
      display: flex;
      height: auto;
      flex-direction: column;
      gap: 40px;
    }
  }

  .main-b-quick {
    min-width: 0;

    &__grid {
      grid-template-columns: repeat(4, 148px);
      grid-template-rows: repeat(3, 136px);
      gap: 12px;
      overflow-x: auto;
      padding: 0 12px;
      scroll-padding-inline: 12px;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;

      &::-webkit-scrollbar {
        display: none;
      }
    }

    .main-b-quick__card {
      padding: 20px 16px;
      border-radius: ds.$radius-md;

      // 1·3열 카드 기준으로 2열씩 넘김
      &:nth-child(odd) {
        scroll-snap-align: start;
      }

      &:hover {
        transform: none;
      }

      strong {
        font-size: 18px;
        line-height: 1.5;
      }
    }

    // 모바일은 카드 폭에 맞춰 자연스럽게 줄바꿈
    .main-b-quick__card--fluid strong span {
      display: inline;
    }
  }

  // 모바일 배너 이미지(336px) 기준으로 넓은 화면에서는 가운데 정렬
  .main-b-promo {
    width: calc(100% - 24px);
    max-width: 336px;
    height: auto;
    margin-inline: auto;
    border-radius: ds.$radius-md;
    aspect-ratio: 336 / 328;

    &__slide {
      border-radius: ds.$radius-md;

      > picture img {
        object-position: center top;
      }
    }
  }

  .main-section-heading {
    min-height: 36px;

    h2 {
      font-size: 28px;
      line-height: 1.3;
      letter-spacing: -0.28px;
    }

    &__more {
      width: 24px;
      height: 24px;
      justify-content: center;
      overflow: hidden;

      &-label {
        position: absolute;
        width: 1px;
        height: 1px;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
      }

      .material-icon {
        width: 24px;
        height: 24px;
        font-size: 24px;
      }
    }
  }

  .main-b-news {
    padding: 40px 20px;

    &__inner {
      gap: 24px;
    }

    &__tabs-scroll {
      width: calc(100% + 20px);
      overflow-x: auto;
      padding-right: 20px;
      scrollbar-width: none;
    }

    &__tabs {
      padding-inline: 8px;
    }

    &__list {
      grid-template-rows: repeat(2, 238px);
      grid-auto-columns: 274px;
      grid-auto-flow: column;
      grid-template-columns: none;
      gap: 16px;
      width: calc(100% + 20px);
      height: 492px;
      overflow-x: auto;
      padding-right: 20px;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
    }

    &__item {
      width: 274px;
      height: 238px;
      scroll-snap-align: start;
    }

    &__title {
      display: -webkit-box;
      font-size: 18px;
      white-space: normal;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: 2;
    }
  }

  .main-b-youtube {
    padding: 40px 20px 80px;

    &__inner {
      gap: 24px;
    }

    &__list {
      display: flex;
      gap: 16px;
      width: calc(100% + 20px);
      overflow-x: auto;
      padding-right: 20px;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
    }

    &__card {
      flex: 0 0 274px;
      height: 265.37px;
      scroll-snap-align: start;
    }

    &__thumbnail {
      height: 162.37px;
      border-radius: 14.452px;
    }

    &__copy {
      gap: 8px;
      padding: 20px 8px 0;

      strong {
        overflow: hidden;
        font-size: 18px;
        line-height: 1.5;
        text-overflow: ellipsis;
        white-space: nowrap;
      }

      > span {
        color: ds.$color-neutral-600;
        font-size: 16px;
        line-height: 1.5;
      }
    }
  }
}

// 360px 미만: 설명 문구가 들어가지 않아 모바일 강제 줄바꿈을 해제
@media (max-width: 359px) {
  .main-b-hero__description .main-b-hero__break--mo {
    display: none;
  }
}

// 유튜브 카드 제목: 말줄임 + 새 창 열림 표시
.main-b-youtube__title-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.main-b-youtube__copy .main-b-youtube__external {
  flex: none;
  font-size: 0.9em;
  font-weight: 400;
}
